1	export interface Item {
2	  readonly type: string;
3	  readonly material?: string;
4	  readonly enchantment?: number;
5	  readonly cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  readonly op: "quote";
10	  readonly items: readonly Item[];
11	}
12	
13	export interface Damage {
14	  readonly itemType: string;
15	  readonly amount: number;
16	}
17	
18	export interface Incident {
19	  readonly cause: string;
20	  readonly damages: readonly Damage[];
21	}
22	
23	export interface ClaimStep {
24	  readonly op: "claim";
25	  readonly policy: number;
26	  readonly incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  readonly yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  readonly customer: Customer;
37	  readonly steps: readonly Step[];
38	}
39	
40	export interface QuoteResult {
41	  readonly premium: number;
42	}
43	
44	export interface ClaimResult {
45	  readonly payout: number;
46	  readonly remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  readonly results: readonly StepResult[];
53	}
54	
55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const isKnownItemType = (type: string): boolean =>
68	  type in BASE_PREMIUM_BY_ITEM_TYPE;
69	
70	const rejectUnknownItemTypes = (items: readonly Item[]): void => {
71	  const unknownItem = items.find((item) => !isKnownItemType(item.type));
72	
73	  if (unknownItem !== undefined) {
74	    throw new Error(`Unknown item type: ${unknownItem.type}`);
75	  }
76	};
77	
78	const itemBasePremiumOf = (item: Item): number =>
79	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
80	
81	const BLOCK_PREMIUM = 60;
82	const BLOCK_SIZE = 3;
83	
84	const itemTypesOf = (items: readonly Item[]): readonly string[] => [
85	  ...new Set(items.map((item) => item.type)),
86	];
87	
88	const itemsGroupedByType = (
89	  items: readonly Item[],
90	): readonly (readonly Item[])[] =>
91	  itemTypesOf(items).map((type) => items.filter((item) => item.type === type));
92	
93	// A component block is a discount on exactly BLOCK_SIZE items of the same type.
94	const sameTypeBasePremiumOf = (sameTypeItems: readonly Item[]): number =>
95	  sameTypeItems.length === BLOCK_SIZE
96	    ? BLOCK_PREMIUM
97	    : sumOf(sameTypeItems, itemBasePremiumOf);
98	
99	const CURSED_SURCHARGE_RATE = 0.5;
100	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
101	const HIGH_ENCHANTMENT_THRESHOLD = 5;
102	
103	const isCursed = (item: Item): boolean => item.cursed === true;
104	
105	const isHighlyEnchanted = (item: Item): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
107	
108	interface Surcharge {
109	  readonly appliesTo: (item: Item) => boolean;
110	  readonly rate: number;
111	}
112	
113	const SURCHARGES: readonly Surcharge[] = [
114	  { appliesTo: isCursed, rate: CURSED_SURCHARGE_RATE },
115	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
116	];
117	
118	const surchargeRateOf = (item: Item): number =>
119	  sumOf(SURCHARGES, (surcharge) =>
120	    surcharge.appliesTo(item) ? surcharge.rate : 0,
121	  );
122	
123	const itemSurchargeOf = (item: Item): number =>
124	  itemBasePremiumOf(item) * surchargeRateOf(item);
125	
126	const policyBasePremiumOf = (items: readonly Item[]): number =>
127	  sumOf(itemsGroupedByType(items), sameTypeBasePremiumOf);
128	
129	const policySurchargeOf = (items: readonly Item[]): number =>
130	  sumOf(items, itemSurchargeOf);
131	
132	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
133	
134	const firstInsuranceSurchargeOf = (basePremium: number): number =>
135	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
136	
137	const LOYALTY_DISCOUNT_RATE = 0.2;
138	const LOYALTY_YEARS_THRESHOLD = 2;
139	
140	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
142	    ? basePremium * LOYALTY_DISCOUNT_RATE
143	    : 0;
144	
145	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
146	
147	const followUpDiscountOf = (
148	  basePremium: number,
149	  previousQuoteCount: number,
150	): number =>
151	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
152	
153	const exactPremiumBeforeFeeOf = (
154	  items: readonly Item[],
155	  customer: Customer,
156	  previousQuoteCount: number,
157	): number => {
158	  const basePremium = policyBasePremiumOf(items);
159	
160	  return (
161	    basePremium +
162	    policySurchargeOf(items) +
163	    firstInsuranceSurchargeOf(basePremium) -
164	    loyaltyDiscountOf(basePremium, customer) -
165	    followUpDiscountOf(basePremium, previousQuoteCount)
166	  );
167	};
168	
169	const PROCESSING_FEE = 5;
170	
171	// Premiums round up and payouts round down: both in the MHPCO's favour.
172	const roundedPremiumInMHPCOsFavour = (premium: number): number =>
173	  Math.ceil(premium);
174	
175	const quotePremiumOf = (
176	  items: readonly Item[],
177	  customer: Customer,
178	  previousQuoteCount: number,
179	): number => {
180	  rejectUnknownItemTypes(items);
181	
182	  return roundedPremiumInMHPCOsFavour(
183	    exactPremiumBeforeFeeOf(items, customer, previousQuoteCount) +
184	      PROCESSING_FEE,
185	  );
186	};
187	
188	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
189	  sword: 1000,
190	  amulet: 600,
191	  rune: 250,
192	};
193	
194	const DEDUCTIBLE = 100;
195	const CAP_FACTOR = 2;
196	
197	const itemInsuranceValueOf = (item: Item): number =>
198	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type];
199	
200	const MASTER_ENCHANTMENT_THRESHOLD = 8;
201	const MASTER_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
202	const FULL_REIMBURSEMENT_RATE = 1;
203	
204	const isMasterEnchanted = (item: Item): boolean =>
205	  (item.enchantment ?? 0) >= MASTER_ENCHANTMENT_THRESHOLD;
206	
207	// Dragon material needs no branch of its own: it is reimbursed in full, which
208	// is already the default rate. Master enchantment overrides that default.
209	const reimbursementRateOf = (item: Item): number =>
210	  isMasterEnchanted(item)
211	    ? MASTER_ENCHANTMENT_REIMBURSEMENT_RATE
212	    : FULL_REIMBURSEMENT_RATE;
213	
214	// A damage entry names an item type, not a particular item, so the terms that
215	// govern it come from an insured item of that type. This lookup also rejects
216	// item types that do not exist at all: an unknown type is, necessarily, not one
217	// the policy insures, so it needs no separate check of its own.
218	const insuredItemOfType = (
219	  itemType: string,
220	  insuredItems: readonly Item[],
221	): Item => {
222	  const insuredItem = insuredItems.find((item) => item.type === itemType);
223	
224	  if (insuredItem === undefined) {
225	    throw new Error(`Item not covered by the policy: ${itemType}`);
226	  }
227	
228	  return insuredItem;
229	};
230	
231	// The reimbursement rate applies to the damage first; the deductible comes off
232	// what is left, not off the damage.
233	const damagePayoutOf = (
234	  damage: Damage,
235	  insuredItems: readonly Item[],
236	): number => {
237	  const insuredItem = insuredItemOfType(damage.itemType, insuredItems);
238	  const reimbursedAmount = damage.amount * reimbursementRateOf(insuredItem);
239	
240	  return reimbursedAmount - DEDUCTIBLE;
241	};
242	
243	// The cap is twice the policy's insurance sum: the unmodified insurance values
244	// of the insured items, untouched by premium modifiers or block discounts.
245	const policyCapOf = (insuredItems: readonly Item[]): number =>
246	  sumOf(insuredItems, itemInsuranceValueOf) * CAP_FACTOR;
247	
248	const entitledPayoutOf = (
249	  incident: Incident,
250	  insuredItems: readonly Item[],
251	): number =>
252	  sumOf(incident.damages, (damage) => damagePayoutOf(damage, insuredItems));
253	
254	// Payouts round down and premiums round up: both in the MHPCO's favour.
255	const roundedPayoutInMHPCOsFavour = (payout: number): number =>
256	  Math.floor(payout);
257	
258	// The cap limits what a policy pays out over its lifetime, so a claim never
259	// pays more than the cap left at the time it is made.
260	const cappedBy = (entitledPayout: number, remainingCap: number): number =>
261	  Math.min(entitledPayout, remainingCap);
262	
263	const claimResultOf = (
264	  step: ClaimStep,
265	  policies: readonly QuoteStep[],
266	  remainingCap: number,
267	): ClaimResult => {
268	  const entitledPayout = entitledPayoutOf(
269	    step.incident,
270	    policies[step.policy].items,
271	  );
272	  const payout = roundedPayoutInMHPCOsFavour(
273	    cappedBy(entitledPayout, remainingCap),
274	  );
275	
276	  return { payout, remainingCap: remainingCap - payout };
277	};
278	
279	const quoteResultOf = (
280	  step: QuoteStep,
281	  customer: Customer,
282	  previousQuoteSteps: readonly QuoteStep[],
283	): QuoteResult => ({
284	  premium: quotePremiumOf(step.items, customer, previousQuoteSteps.length),
285	});
286	
287	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
288	
289	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
290	  steps.filter(isQuoteStep);
291	
292	const quoteStepsBefore = (
293	  steps: readonly Step[],
294	  stepIndex: number,
295	): readonly QuoteStep[] => quoteStepsOf(steps.slice(0, stepIndex));
296	
297	// The state a scenario carries from one step to the next: the results produced
298	// so far, and how much of each policy's cap is still available.
299	interface ScenarioState {
300	  readonly results: readonly StepResult[];
301	  readonly remainingCaps: readonly number[];
302	}
303	
304	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
305	  results: [],
306	  remainingCaps: policies.map((policy) => policyCapOf(policy.items)),
307	});
308	
309	const capsAfterClaim = (
310	  remainingCaps: readonly number[],
311	  policy: number,
312	  remainingCap: number,
313	): readonly number[] =>
314	  remainingCaps.map((cap, index) => (index === policy ? remainingCap : cap));
315	
316	const stateAfterQuote = (
317	  state: ScenarioState,
318	  result: QuoteResult,
319	): ScenarioState => ({ ...state, results: [...state.results, result] });
320	
321	const stateAfterClaim = (
322	  state: ScenarioState,
323	  step: ClaimStep,
324	  result: ClaimResult,
325	): ScenarioState => ({
326	  results: [...state.results, result],
327	  remainingCaps: capsAfterClaim(
328	    state.remainingCaps,
329	    step.policy,
330	    result.remainingCap,
331	  ),
332	});
333	
334	export const runScenario = (scenario: Scenario): ScenarioResult => {
335	  const policies = quoteStepsOf(scenario.steps);
336	
337	  const { results } = scenario.steps.reduce(
338	    (state, step, stepIndex) =>
339	      isQuoteStep(step)
340	        ? stateAfterQuote(
341	            state,
342	            quoteResultOf(
343	              step,
344	              scenario.customer,
345	              quoteStepsBefore(scenario.steps, stepIndex),
346	            ),
347	          )
348	        : stateAfterClaim(
349	            state,
350	            step,
351	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
352	          ),
353	    initialStateOf(policies),
354	  );
355	
356	  return { results };
357	};
